use std::fmt;
use std::io::{self, BufRead};

struct Row {
    name: String,
    subject: String,
    score: u32,
}

enum RowError {
    FieldCount,
    EmptyName,
    EmptySubject,
    BadScore(String),
    OutOfRange(i64),
}

impl fmt::Display for RowError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RowError::FieldCount => write!(f, "expected 3 fields"),
            RowError::EmptyName => write!(f, "empty name"),
            RowError::EmptySubject => write!(f, "empty subject"),
            RowError::BadScore(t) => write!(f, "bad score '{t}'"),
            RowError::OutOfRange(n) => write!(f, "score {n} out of range"),
        }
    }
}

fn parse_row(line: &str) -> Result<Row, RowError> {
    let fields: Vec<&str> = line.split(',').map(str::trim).collect();
    let [name, subject, score] = fields[..] else {
        return Err(RowError::FieldCount);
    };
    if name.is_empty() {
        return Err(RowError::EmptyName);
    }
    if subject.is_empty() {
        return Err(RowError::EmptySubject);
    }
    let n: i64 = score.parse().map_err(|_| RowError::BadScore(score.to_string()))?;
    if !(0..=100).contains(&n) {
        return Err(RowError::OutOfRange(n));
    }
    Ok(Row { name: name.to_string(), subject: subject.to_string(), score: n as u32 })
}

mod report {
    use super::Row;
    use std::collections::BTreeMap;

    fn grade(avg: f64) -> char {
        match avg {
            a if a >= 90.0 => 'A',
            a if a >= 80.0 => 'B',
            a if a >= 70.0 => 'C',
            a if a >= 60.0 => 'D',
            _ => 'F',
        }
    }

    fn average(scores: &[u32]) -> f64 {
        scores.iter().sum::<u32>() as f64 / scores.len() as f64
    }

    pub fn lines(rows: &[Row]) -> Vec<String> {
        let mut by_student: BTreeMap<&str, Vec<u32>> = BTreeMap::new();
        let mut by_subject: BTreeMap<&str, Vec<(&str, u32)>> = BTreeMap::new();
        for r in rows {
            by_student.entry(&r.name).or_default().push(r.score);
            by_subject.entry(&r.subject).or_default().push((&r.name, r.score));
        }

        let mut students: Vec<(&str, f64, usize)> =
            by_student.iter().map(|(name, s)| (*name, average(s), s.len())).collect();
        students.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap().then_with(|| a.0.cmp(b.0)));

        let mut out = vec!["Students:".to_string()];
        for (name, avg, n) in students {
            let plural = if n == 1 { "result" } else { "results" };
            out.push(format!("  {name:<10} {avg:>5.1} {}  ({n} {plural})", grade(avg)));
        }
        out.push("Subjects:".to_string());
        for (subject, entries) in &by_subject {
            let scores: Vec<u32> = entries.iter().map(|e| e.1).collect();
            let mut best = entries[0];
            for &e in entries {
                if e.1 > best.1 || (e.1 == best.1 && e.0 < best.0) {
                    best = e;
                }
            }
            out.push(format!("  {subject:<10} avg {:.1}  best {} ({})", average(&scores), best.0, best.1));
        }
        out
    }
}

fn main() {
    let mut lines = io::stdin().lock().lines();
    let header = lines.next().and_then(|l| l.ok()).unwrap_or_default();
    if header.trim() != "name,subject,score" {
        println!("error: bad header");
        return;
    }
    let mut rows = Vec::new();
    let mut errors = 0;
    for (i, line) in lines.enumerate() {
        let line = line.unwrap();
        if line.trim().is_empty() {
            continue;
        }
        match parse_row(&line) {
            Ok(row) => rows.push(row),
            Err(e) => {
                println!("line {}: {e}", i + 2);
                errors += 1;
            }
        }
    }
    if rows.is_empty() {
        println!("No data.");
    } else {
        for l in report::lines(&rows) {
            println!("{l}");
        }
    }
    println!("Errors: {errors}");
}
